import {rareDiscoveries} from './rare-content.js';
import {extendedDiscoveries} from './extended-content.js';
export const discoveries=[
{id:'waves',name:'The Wave Garden',concept:'Wave interference',field:'TRIGONOMETRY',color:'#84dacb',symbol:'∿',pos:[20,3,-36],size:5.8,question:'When can two waves become silence?',invitation:'Slide the phase. Watch the two waves combine.',controls:[{id:'phase',label:'Phase difference',min:0,max:360,step:1,value:70,unit:'°'}],caption:'Cyan + amber = white. The white wave is their sum.',intuition:'Two waves add point by point. Peaks can reinforce each other, or meet troughs and cancel. The waves have equal amplitude and frequency here.',math:'<span class="formula">sin(x) + sin(x + φ)</span>Resulting amplitude = 2|cos(φ/2)|. In the equation, φ is measured in radians. The control displays degrees.',why:'The sine addition identity rewrites the sum as 2 cos(φ/2) sin(x + φ/2). At 180°, cos(φ/2) = 0, so cancellation occurs at every point. Different frequencies would not stay cancelled.',challenge:{q:'What phase difference makes these equal waves cancel everywhere?',options:['0° — perfectly aligned','90° — a quarter turn','180° — opposite phases'],correct:2,explain:'At 180°, every peak meets an equal trough. Their point-by-point sum is zero.'},related:'derivatives'},
{id:'vectors',name:'The Vector Drift',concept:'Vector addition',field:'LINEAR ALGEBRA',color:'#93b9fa',symbol:'↗',pos:[-13,13,-67],size:4.7,question:'Where do two directions take you?',invitation:'Drag the blue arrow tip, or change its two components.',controls:[{id:'x',label:'Blue vector · horizontal',min:-4,max:4,step:.1,value:2},{id:'y',label:'Blue vector · vertical',min:-3,max:3,step:.1,value:1}],caption:'Blue a + amber b = mint a + b. The dashed path shows tip-to-tail addition.',intuition:'A vector carries a direction and a length. Follow the blue arrow, then the amber arrow. The mint arrow reaches the same final point in one step.',math:'<span class="formula">a + b = (aₓ + bₓ, aᵧ + bᵧ)</span>The amber vector is fixed at b = (2, 1). Blue is controlled by you. Length is √(x² + y²).',why:'Translations combine by adding their horizontal and vertical displacements separately. Reversing their order gives the same endpoint: a + b = b + a. These are displacement vectors, not a physical force simulation.',challenge:{q:'Which blue vector cancels the amber vector (2, 1)?',options:['(2, 1)','(−2, −1)','(−1, −2)'],correct:1,explain:'Opposite components cancel: (−2 + 2, −1 + 1) = (0, 0).'},related:'pythagoras'},
{id:'fractals',name:'The Infinite Branch',concept:'Recursion & self-similarity',field:'PATTERNS',color:'#c1a0f5',symbol:'⋔',pos:[42,23,-106],size:6.8,question:'How much can one simple rule create?',invitation:'Change the depth. Every branch repeats the same rule.',controls:[{id:'depth',label:'Recursion depth',min:0,max:9,step:1,value:6},{id:'angle',label:'Branching angle',min:12,max:65,step:1,value:28,unit:'°'},{id:'ratio',label:'Child / parent length',min:.45,max:.74,step:.01,value:.65}],caption:'A finite recursive tree. Each branch makes two shorter children.',intuition:'Start with one branch. At its tip, create two smaller branches. Apply the same instruction again. Complexity emerges from a short, repeated rule.',math:'<span class="formula">N(d) = 2⁽ᵈ⁺¹⁾ − 1</span>At depth d, the drawing contains 1 + 2 + 4 + … + 2ᵈ segments. A branch at level k has length L₀rᵏ.',why:'There are twice as many branches at each level. Summing this geometric series gives the count. This screen draws a finite approximation; it does not contain infinitely many branches. At a fixed ratio, each child subtree repeats the same shape.',challenge:{q:'At depth 3, how many segments exist, including the trunk?',options:['8','15','16'],correct:1,explain:'Count every level: 1 + 2 + 4 + 8 = 15 segments.'},related:'volume'},
{id:'derivatives',name:'The Edge of Change',concept:'Derivatives & limits',field:'CALCULUS',color:'#efbd81',symbol:'∂',pos:[-42,-9,-125],size:7,question:'What does change look like at one instant?',invitation:'Bring the two points closer. Watch the secant approach the tangent.',controls:[{id:'x',label:'Position x',min:-2,max:2,step:.05,value:1},{id:'h',label:'Gap h between points',min:.02,max:1.5,step:.01,value:1}],caption:'Parabola f(x) = x² · amber secant · cyan tangent at the blue point.',intuition:'The amber line measures average change between two points. As their gap shrinks, its slope approaches the slope at the first point: the derivative.',math:'<span class="formula">f′(x) = limₕ→₀ [(x+h)² − x²] / h = 2x</span>For a nonzero gap, the secant slope is 2x + h. The tangent slope is exactly 2x.',why:'Expand (x+h)² to obtain x² + 2xh + h². Subtract x² and divide by h ≠ 0 to get 2x + h. Taking the limit gives 2x. A tiny gap illustrates the limit; the algebra establishes it.',challenge:{q:'For f(x) = x², what is the instantaneous slope at x = −1?',options:['−2','0','2'],correct:0,explain:'The derivative is 2x, so at x = −1 the slope is −2. The curve is decreasing there.'},related:'waves'},
{id:'probability',name:'The Chance Cloud',concept:'Probability & frequency',field:'PROBABILITY',color:'#ef96ba',symbol:'%',pos:[60,-25,-150],size:6,question:'Can randomness reveal a pattern?',invitation:'Set the chance of a pink outcome. Run a batch and compare.',controls:[{id:'p',label:'Chance of pink',min:0,max:100,step:1,value:50,unit:'%'}],caption:'Each point is an independent trial. Pink is a success; blue is the other outcome.',intuition:'A probability describes a chance, not a promise about the next result. The observed proportion can wander in small samples. Larger samples tend to be closer to the underlying probability.',math:'<span class="formula">Observed frequency = successes / trials</span>Expected successes = n × p. For independent Bernoulli trials, the standard deviation of the count is √(np(1−p)).',why:'Independent trials with the same probability satisfy the law of large numbers. Their observed proportion converges to p in probability as the number of trials increases. It need not get closer after every batch, and earlier outcomes do not create a debt to repay.',challenge:{q:'With independent fair trials, five pink outcomes just occurred. What is the chance of pink next?',options:['Less than 50%','Exactly 50%','More than 50%'],correct:1,explain:'Independence means the previous outcomes do not change the next trial’s 50% chance. The universe keeps no scorecard.'},related:'fractals'},
{id:'pythagoras',name:'The Right Connection',concept:'Pythagorean theorem',field:'GEOMETRY',color:'#acd888',symbol:'△',pos:[-67,26,-175],size:5.4,question:'Why do these three squares belong together?',invitation:'Change the legs. Compare the areas of the attached squares.',controls:[{id:'a',label:'Horizontal leg a',min:1,max:4,step:.1,value:3},{id:'b',label:'Vertical leg b',min:1,max:4,step:.1,value:4}],caption:'The right angle is fixed. Colored squares measure the areas a², b² and c².',intuition:'For every right triangle in a flat plane, the two smaller square areas add up to the area of the square on the longest side. Changing the lengths preserves that relationship.',math:'<span class="formula">a² + b² = c²</span>c = √(a² + b²). The lengths do not add this way; their squares do. The triangle must have a right angle.',why:'A square of side a+b can contain four copies of this right triangle around an inner square of side c. Its area is (a+b)² = 4(ab/2) + c². Expanding and cancelling 2ab leaves a²+b²=c². The live diagram illustrates the relationship; this area argument proves it.',challenge:{q:'A right triangle has legs 6 and 8. What is its hypotenuse?',options:['14','10','100'],correct:1,explain:'6² + 8² = 100, so the hypotenuse is √100 = 10. The area is 100; the length is 10.'},related:'vectors'},
{id:'volume',name:'The Scale Paradox',concept:'Volume & scaling',field:'GEOMETRY',color:'#83d3ec',symbol:'³',pos:[12,-18,-210],size:8,question:'Twice as big. Eight times the space?',invitation:'Scale the object. Compare length, surface area, and volume.',controls:[{id:'s',label:'Scale every dimension',min:1,max:3,step:.1,value:1.5}],caption:'Original cube on the left. The right cube scales along all three axes.',intuition:'Scaling every dimension changes more than the visible width. A cube twice as wide, twice as tall, and twice as deep holds eight original cubes. The warehouse noticed.',math:'<span class="formula">Length × s · Area × s² · Volume × s³</span>For a unit cube scaled by s: side = s, surface area = 6s², volume = s³.',why:'Volume multiplies three independent lengths. Therefore (sw)(sh)(sd) = s³whd. Surface area has two length factors and scales as s². This applies to uniform scaling; changing only one dimension follows a different rule.',challenge:{q:'Triple all dimensions. By what factor does volume change?',options:['3×','9×','27×'],correct:2,explain:'Three independent factors: 3 × 3 × 3 = 27. Surface area increases by 9×.'},related:'fractals'}
];

discoveries.push(...extendedDiscoveries);

discoveries.push(...rareDiscoveries);
